const out = $input.first().json.stdout || [];
const text = out.join('');
let result = {};
try { result = JSON.parse(text); } catch(e) {}

const ok = result.ok;
const count = result.issue_count || 0;
const checks = result.checks || {};

const lines = [];
if (ok) {
  lines.push('✅ 数据巡检通过');
} else {
  lines.push(`⚠️ 发现 ${count} 个问题`);
}

for (const [key, issues] of Object.entries(checks)) {
  if (issues.length > 0) {
    for (const i of issues) lines.push(i);
  } else {
    lines.push(`  ${key}: OK`);
  }
}

return [{ json: { summary: lines.join('\n'), ok, issues: count } }];
